actions.action:
// Economic nexus established per factor presence standards - filing required
// ME thresholds:
// - $250,000 in property
// - $250,000 in payroll
// - $500,000 in sales
// - OR 25% of total property, payroll, or sales in ME
// Apportionment will be calculated by tables 7000-7500

// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate state additions (ME-specific)
            double additions = 0.0;

            // ME requires addback of IRC 199A deduction (ME doesn't conform)
            // additions += result.section_199a_deduction;

            // ME requires addback of certain depreciation differences
            // additions += result.federal_me_depreciation_difference;

            // ME requires addback of safe harbor lease deductions
            // additions += result.safe_harbor_lease_deduction;

            apportionment.state_additions = additions;

            // Calculate state subtractions (ME-specific)
            double subtractions = 0.0;

            // ME allows subtraction for federal bond interest (exempt from ME tax)
            // subtractions += revenue.federal_bond_interest;

            // ME allows subtraction for Maine municipal bond interest
            // subtractions += revenue.maine_municipal_bond_interest;

            // ME allows deduction for dividends from subsidiaries (95% deduction)
            // subtractions += revenue.qualified_dividend_deduction;

            // ME NOL deduction
            // subtractions += result.me_nol_deduction;

            apportionment.state_subtractions = subtractions;

condition.expression:
if (apportionment.state_taxable_income <= 350000.0) { "tier1"; }
else if (apportionment.state_taxable_income <= 1050000.0) { "tier2"; }
else if (apportionment.state_taxable_income <= 3500000.0) { "tier3"; }
else { "tier4"; }

actions.action:
            // ME graduated rate tier 1: 3.5% on income up to $350,000
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.tax_rate_tier1;

            // Subtract state credits (Pine Tree Zone, R&D, employment credits, etc.)
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // ME graduated rate tier 2:
            // First $350,000 at 3.5% + excess at 7.5%
            double tier1_tax = 350000.0 * apportionment.tax_rate_tier1;
            double tier2_income = apportionment.state_taxable_income - 350000.0;
            double tier2_tax = tier2_income * apportionment.tax_rate_tier2;

            apportionment.state_tax = tier1_tax + tier2_tax;

            // Subtract state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // ME graduated rate tier 3:
            // First $350,000 at 3.5% + next $700,000 at 7.5% + excess at 8.3%
            double tier1_tax = 350000.0 * apportionment.tax_rate_tier1;
            double tier2_tax = 700000.0 * apportionment.tax_rate_tier2;
            double tier3_income = apportionment.state_taxable_income - 1050000.0;
            double tier3_tax = tier3_income * apportionment.tax_rate_tier3;

            apportionment.state_tax = tier1_tax + tier2_tax + tier3_tax;

            // Subtract state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // ME graduated rate tier 4:
            // First $350,000 at 3.5% + next $700,000 at 7.5% +
            // next $2,450,000 at 8.3% + excess at 8.93%
            double tier1_tax = 350000.0 * apportionment.tax_rate_tier1;
            double tier2_tax = 700000.0 * apportionment.tax_rate_tier2;
            double tier3_tax = 2450000.0 * apportionment.tax_rate_tier3;
            double tier4_income = apportionment.state_taxable_income - 3500000.0;
            double tier4_tax = tier4_income * apportionment.tax_rate_tier4;

            apportionment.state_tax = tier1_tax + tier2_tax + tier3_tax + tier4_tax;

            // Subtract state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
